/* Timing. Beat times come from the voiceover: voiceover/timings.json is generated by scripts/yt/vo-build.py
   from the takes (word-level alignment + assembly.json). Scenes read beat and word times, never seconds, so a
   re-take moves the picture with the voice. */
import { SCRIPT_BEATS } from './script';
import timings from '../../../../youtube/02_videos/2026-W46_bulk-domain-redirects/voiceover/timings.json';

export type Timed = {
    n: number; at: number; dur: number; end: number; vo: string;
    voStart: number | null; voEnd: number | null;
    words: readonly { w: string; s: number; e: number }[];
};

export const BEATS: readonly Timed[] = timings.beats.map((b, i) => {
    if (SCRIPT_BEATS[i]?.n !== b.n) throw new Error(`timings.json beat ${b.n} does not match script beat ${SCRIPT_BEATS[i]?.n}; re-run scripts/yt/vo-build.py`);
    return { n: b.n, at: b.at, dur: b.end - b.at, end: b.end, vo: SCRIPT_BEATS[i].vo, voStart: b.voStart, voEnd: b.voEnd, words: b.words };
});

/** Film length in whole seconds (the end card runs to the last frame). music.json must say the same. */
export const TOTAL = Math.ceil(BEATS[BEATS.length - 1].end);

export const at = (n: number) => BEATS[n - 1].at;
export const end = (n: number) => BEATS[n - 1].end;
const key = (w: string) => w.toLowerCase().replace(/[^a-z0-9']/g, '');
/** Absolute start of the k-th (default first) word of beat n that matches `w`. Throws if missing, so a re-take
    that drops a word fails the build instead of silently mistiming a visual. Domains are matched as spoken
    ("get", "frosty", "fusion", "dot", "com"). */
export function word(n: number, w: string, k = 0): number {
    const hits = BEATS[n - 1].words.filter((x) => key(x.w) === key(w));
    if (!hits[k]) throw new Error(`beat ${n} has no word "${w}" (#${k + 1})`);
    return hits[k].s;
}
/** End of the k-th word of beat n that matches `w`. */
export function wordEnd(n: number, w: string, k = 0): number {
    const hits = BEATS[n - 1].words.filter((x) => key(x.w) === key(w));
    if (!hits[k]) throw new Error(`beat ${n} has no word "${w}" (#${k + 1})`);
    return hits[k].e;
}
/** End of the last spoken word of beat n. */
export const voEnd = (n: number) => BEATS[n - 1].voEnd ?? end(n);
/** The knock's cue (its first rap; the sound and the arcs both read it), twice: just after "when someone knocks"
    (beat 11, w46-Door) and "could hear the knocks" (beat 25, w46-Knocks). */
export const knockAt = (i: 1 | 2) => (i === 1 ? wordEnd(11, 'knocks') : wordEnd(25, 'knocks')) + 0.06;

/** Scene windows: [first beat, last beat], one scene per approved key frame (keyframes.md). Beats 10, 20-21 and
    31-32 are shared by two frames; those scenes split their beat on a word (see the scene). */
export const SCENES = {
    notebook: [1, 2], glomvo: [3, 3], title: [4, 4],
    renewals: [5, 5], parking: [6, 6], weight: [7, 7],
    two: [8, 9], warning: [10, 10],
    door: [11, 11], honest: [12, 12], once: [13, 13],
    list: [14, 15], columns: [16, 17], product: [18, 21], dns: [22, 23], padlocks: [24, 24],
    knocks: [25, 26], price: [27, 27], quiet: [28, 28], bytag: [29, 29],
    recap: [30, 30], yours: [31, 32], end: [33, 33],
} as const;
export type SceneKey = keyof typeof SCENES;
/** Each scene starts `LAP` s before its first beat so it can fade in over the outgoing one. */
export const LAP = 0.3;

export function sceneWindow(k: SceneKey): readonly [number, number] {
    const [a, b] = SCENES[k];
    const start = k === 'notebook' ? 0 : Math.max(0, at(a) - LAP);
    return [start, k === 'end' ? TOTAL : end(b)];
}

/** Scene-local time helpers. */
export function local(k: SceneKey) {
    const [s, e] = sceneWindow(k);
    return {
        at: (n: number) => at(n) - s, end: (n: number) => end(n) - s, voEnd: (n: number) => voEnd(n) - s,
        word: (n: number, w: string, i = 0) => word(n, w, i) - s, wordEnd: (n: number, w: string, i = 0) => wordEnd(n, w, i) - s,
        start: s, len: e - s,
    };
}
export type Local = ReturnType<typeof local>;
